 action($('#lr-save-draft'),async()=>{const current=activeDraft(s);if(!current)throw Error('Önce taslak hazırla.');const d=compose().edit(s,current.id,draftFields(),{delivery:delivery(s)});await commit(compose().save(s,d),s);ctx.message('Düzenlenen ilan sürümü ve dayanağı kaydedildi.');});
