 action($('#lr-export-report'),()=>ctx.downloadJSON(compose().exportReport(s,{delivery:delivery(s)}),'arastirma-'+s.id+'.json'));
 action($('#lr-adopt-draft'),()=>renderAdoptPreview(s));
